  q.put("output",root.getParent().resolve("outside.xlsx").toString());check(call(t,q).isError,"output outside workdir refused");q.put("output",root.resolve("bad.xlsx").toString());q.put("input",root.resolve("settings.properties").toString());Files.writeString(root.resolve("settings.properties"),"fixture secret");check(call(t,q).isError,"settings path blocked");
